CREATE TABLE customer_onboarding_requests (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(120) NOT NULL, email VARCHAR2(150) NOT NULL UNIQUE, mobile_number VARCHAR2(20) NOT NULL, pan_number VARCHAR2(10) NOT NULL UNIQUE, status VARCHAR2(20) NOT NULL, review_comment VARCHAR2(500), reviewed_by VARCHAR2(80), reviewed_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX idx_onboarding_status ON customer_onboarding_requests(status);
